410:bool SpaceStation::OnCollision(Body *b, Uint32 flags, double relVel)
411-{
412-	if (!b->IsType(ObjectType::SHIP)) return true;
413-	if (!(flags & (SceneGraph::CollisionGeometry::DOCKING | SceneGraph::CollisionGeometry::ENTRANCE))) return true;
414-
415-	Ship *s = static_cast<Ship *>(b);
416-	if(s->ManualDocking() && (flags & SceneGraph::CollisionGeometry::ENTRANCE)) return false;
417-
418-	bool touchOrbitalPad = (flags & SceneGraph::CollisionGeometry::DOCKING) && !IsGroundStation();
419-
420-	int bay = -1;
421-	for (Uint32 i = 0; i < m_shipDocking.size(); i++) {
422-		if (m_shipDocking[i].ship == s) {
423-			bay = i;
424-			break;
425-		}
426-	}
427-
428-	bool bayUnavailable = bay == -1 || IsPortLocked(bay) || m_shipDocking[bay].stage == DockStage::NONE;
429-	if (bayUnavailable) {
430-		return DoShipDamage(s, flags, relVel);
431-	}
432-
433-	if (IsGroundStation() || touchOrbitalPad) {
434-		// must be oriented sensibly and have wheels down
435-		matrix4x4d bayTrans = GetBayTransform(bay);
436-
437-		vector3d dockingNormal = bayTrans.Up();
438-		const double dot = s->GetOrient().VectorY().Dot(dockingNormal);
439-		if ((dot < 0.99) || (s->GetWheelState() < 1.0))
440-		{
441-			return DoShipDamage(s, flags, relVel); // <0.99 harsh?
442-		}
443-		// check speed
444-		if (s->GetVelocity().Length() > MAX_LANDING_SPEED)
445-		{
446-			return DoShipDamage(s, flags, relVel);
447-		}
448-		// check if you're near your pad
449-		float dist = (s->GetPosition() - bayTrans.GetTranslate()).LengthSqr();
450-		// docking allowed only if inside a circle 70% greater than pad itself (*1.7)
451-		float maxDist = static_cast<float>(m_type->FindPortByBay(bay)->maxShipSize / 2) * 1.7;
452-		if (dist > (maxDist * maxDist))
453-		{
454-			return DoShipDamage(s, flags, relVel);
455-		}
456-	}
457-
458-	// docking is in progress
459-	if (s->GetFlightState() == Ship::DOCKING) return false;
460-
461-	// launch docking
462-	// set up a control structure
463-	// from now on, the location of the ship will be set by the station using this data
464-	shipDocking_t &sd = m_shipDocking[bay];
465-	sd.ship = s;
466-	sd.stagePos = 0;
467-	// capture the current location of the ship
468-	sd.fromPos = (s->GetPosition() - GetPosition()) * GetOrient(); // station space
469-	sd.fromRot = Quaterniond::FromMatrix3x3(GetOrient().Transpose() * s->GetOrient());
470-	// prepare the ship for passive existence
471-	s->SetFlightState(Ship::DOCKING);
472-	s->SetVelocity(vector3d(0.0));
473-	s->SetAngVelocity(vector3d(0.0));
474-	s->ClearThrusterState();
475-
476-	SwitchToStage(bay, (touchOrbitalPad || m_type->NumUndockStages() == 0) ? DockStage::TOUCHDOWN : DockStage::DOCK_ANIMATION_1);
