import re,sys
import xml.etree.ElementTree as ET
ns={'c':'http://www.collada.org/2005/11/COLLADASchema'}
t=ET.parse(sys.argv[1]); r=t.getroot()
geos={}
for g in r.iter('{%s}geometry'%ns['c']):
    m=g.find('c:mesh',ns)
    if m is None: continue
    pos=None
    vin=m.find('c:vertices/c:input[@semantic="POSITION"]',ns)
    src=vin.get('source')[1:]
    for s in m.findall('c:source',ns):
        if s.get('id')==src:
            pos=[float(x) for x in s.find('c:float_array',ns).text.split()]
    geos[g.get('id')]=[pos[i:i+3] for i in range(0,len(pos),3)]
def mul(A,B): return [[sum(A[i][k]*B[k][j] for k in range(4)) for j in range(4)] for i in range(4)]
def walk(n,M,out):
    mt=n.find('c:matrix',ns)
    if mt is not None:
        v=[float(x) for x in mt.text.split()]; M=mul(M,[v[0:4],v[4:8],v[8:12],v[12:16]])
    for ig in n.findall('c:instance_geometry',ns):
        g=geos[ig.get('url')[1:]]
        zs=[M[2][0]*p[0]+M[2][1]*p[1]+M[2][2]*p[2]+M[2][3] for p in g]
        out.append((min(zs),max(zs),n.get('name'),len(g)))
    if not n.findall('c:instance_geometry',ns) and n.get('name','').startswith('tag'):
        out.append((M[2][3],M[2][3],n.get('name'),0))
    for c in n.findall('c:node',ns): walk(c,M,out)
I=[[1 if i==j else 0 for j in range(4)] for i in range(4)]
out=[]
for vs in r.iter('{%s}visual_scene'%ns['c']):
    for n in vs.findall('c:node',ns): walk(n,I,out)
for o in sorted(out)[:int(sys.argv[2]) if len(sys.argv)>2 else 15]: print('%.3f %.3f %s %d'%o)
E
python3 -I /tmp/zmin.py coronatrix_coll.dae; echo; python3 -I /tmp/zmin.py coronatrix_hi.dae 12

